const auth = $input.first().json;
const email = 'xiaojing002@e.ntu.edu.sg';
const mode = auth.Mode;
if (!['Simulation','Formal sponsor change'].includes(mode)) throw new Error('Choose a valid change mode.');
const req = (key, max) => {
  const value = typeof auth[key] === 'string' ? auth[key].trim() : '';
  if (!value || value.length > max) throw new Error('Invalid '+key);
  return value;
};
const reference = req('Event reference',150);
const citation = req('Source citation',500);
const facts = req('Event facts',6000);
const ids = [...new Set(String(auth['Affected WBS or milestone IDs'] ?? '').toUpperCase().split(/[\\s,;]+/).filter(Boolean))];
if (ids.some(id => !/^(HCH(?:-[0-9]+)*|M[0-9]+)$/.test(id))) throw new Error('Invalid WBS or milestone ID');
const formal = mode === 'Formal sponsor change';
if (formal && (!/^CE-0[12]$/.test(reference) || /simulation|test scenario/i.test(facts))) {
  throw new Error('For a formal change, supply CE-01 or CE-02 and its actual memo.');
}
const risks = [...new Set(String(auth['Risk IDs']??'').toUpperCase().split(/[\\s,;]+/).filter(Boolean))];
if(risks.some(id=>!/^R\\d+$/.test(id))) throw new Error('Invalid risk ID');
const result = {module:'W06_CHANGE',mode,reference,citation,facts,affected_ids:ids,
  detected_at:new Date().toISOString(),received_by:email,execution_id:String($execution.id),
  stale:{plan:{status:'REVIEW_REQUIRED',ids,next:'Review the cited items, predecessor/successor dependencies and milestone dates against sponsor evidence.'},
    risk_register:{status:'REVIEW_REQUIRED',ids:risks,next:'Review linked risks and revise trigger, owner, likelihood and impact. Keep unsupported values pending.'},
    reports:{status:'STALE',outputs:['Weekly Committee Update','Monthly Grant Report'],next:'Regenerate both from the reconciled facts and rerun the critic before release.'}},
  draft_actions:['Confirm sponsor authority and effective date','Reconcile affected scope, dates, cost and assumptions','Record revised baseline and obtain new Jira approval'],
  approval_status:'PENDING',evidence_status:formal?'FORMAL_MEMO_ENTERED':'SIMULATION_ONLY',jira_write_blocked:formal};
return [{json:{payload:JSON.stringify(result),state:formal?'CHANGE_OPEN':'CHANGE_TEST',source_version:reference,audit:JSON.stringify(result)}}];

const row=$input.first().json;
if(!row.id) throw new Error('Change record was not saved.');
return [{json:{change_record:row.id,state:row.state,...JSON.parse(row.audit)}}];
